[checks/lease-transfer.demo.js]
{
  "operation": "Registry.transfer default TTL",
  "before": {
    "lease": {
      "resource": "resource-r",
      "holder": "alice",
      "token": "lease-904141-1-1-rs",
      "expiresAt": 1050,
      "epoch": 1
    },
    "stats": {
      "granted": 1,
      "renewed": 0,
      "released": 0,
      "reclaimed": 0,
      "live": 1
    },
    "epoch": 2
  },
  "input": {
    "token": "lease-904141-1-1-rs",
    "holder": "bob"
  },
  "response": {
    "outcome": "returned",
    "value": {
      "resource": "resource-r",
      "holder": "bob",
      "token": "lease-904141-1-2-rs",
      "expiresAt": 1100,
      "epoch": 2
    }
  },
  "after": {
    "holder": "bob",
    "epoch": 2,
    "stats": {
      "granted": 1,
      "renewed": 0,
      "released": 0,
      "reclaimed": 0,
      "live": 1
    },
    "oldCredential": {
      "renew": {
        "outcome": "returned",
        "value": false
      },
      "release": {
        "outcome": "returned",
        "value": false
      },
      "assertLease": {
        "outcome": "threw",
        "error": {
          "name": "LeaseFencedError",
          "code": "LEASE_FENCED",
          "message": "lease for resource resource-r is fenced"
        }
      }
    },
    "newCredential": {
      "assertLease": {
        "outcome": "returned",
        "value": true
      }
    }
  }
}
{
  "operation": "transfer a credential from a declared shareable resource with capacity 1",
  "input": {
    "resource": "single-share-pool",
    "capacity": 1,
    "token": "lease-904141-2-1-1jk",
    "holder": "bob",
    "ttlMs": 100
  },
  "response": {
    "outcome": "returned",
    "value": {
      "resource": "single-share-pool",
      "holder": "bob",
      "token": "lease-904141-2-2-1jk",
      "expiresAt": 2100,
      "epoch": 2
    }
  },
  "expectedPublicResult": "LeaseFencedError with code LEASE_FENCED",
  "assertion": "UNEXPECTED"
}

